type Product={id:number;sku?:string;name:string;size:string;color:string;description:string;price:number;regularPrice?:number|null;image:string;category:string;availability:string;canOrder:boolean;featured:boolean;groupId?:string|null;groupName?:string;optionNames?:string[];variantOptions?:Record<string,string>};
