type Receipt={id:number;number:string;date:string;total:number;status:string;method:string;locationId?:number;storeName?:string;currency?:string;capturedAt?:string;subtotal?:number;discount?:number;vat?:number;paid?:number;returned?:number;saleStatus?:string;lines?:{name:string;quantity:number;price:number;discount:number}[]};
