type Account={customer:{name:string;email:string;balance?:number};capturedAt:string;orders:Order[];quoteRequests?:QuoteRequest[];designApprovals?:DesignProof[];designApprovalHistory?:DesignEvent[];stores?:AccountStore[];receipts:Receipt[];favorites?:{id:number}[]};
let csrf='';
async function api<T>(route:string,body:object={}):Promise<T>{
  const response=await fetch('/shop/api/v1/'+route,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Storefront-Request':'same-origin',...(csrf?{'X-CSRF-Token':csrf}:{})},body:JSON.stringify(body)});
  let result;try{result=await response.json();}catch{throw new Error('The store is temporarily unavailable. Your bag is saved.');}
  if(!response.ok){if(route==='checkout'&&result.checkoutClosed===true)localStorage.removeItem('deckers.checkout');throw new Error(result.message||'Please try again.');}return result;
}
